CREATE COLUMN TABLE "UAT_JBF2"."ITT1" ("Father" NVARCHAR(50) NOT NULL , "ChildNum" INTEGER CS_INT NOT NULL , "VisOrder" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(50), "Quantity" DECIMAL(21,6) CS_FIXED, "Warehouse" NVARCHAR(8), "Price" DECIMAL(21,6) CS_FIXED, "Currency" NVARCHAR(3), "PriceList" SMALLINT CS_INT DEFAULT 0, "OrigPrice" DECIMAL(21,6) CS_FIXED, "OrigCurr" NVARCHAR(3), "IssueMthd" NVARCHAR(1), "Uom" NVARCHAR(100), "Comment" NVARCHAR(254), "LogInstanc" INTEGER CS_INT, "Object" NVARCHAR(20) DEFAULT '66', "OcrCode" NVARCHAR(8), "OcrCode2" NVARCHAR(8), "OcrCode3" NVARCHAR(8), "OcrCode4" NVARCHAR(8), "OcrCode5" NVARCHAR(8), "PrncpInput" NVARCHAR(1) DEFAULT 'N', "Project" NVARCHAR(20), "Type" INTEGER CS_INT DEFAULT 4, "WipActCode" NVARCHAR(15), "AddQuantit" DECIMAL(21,6) CS_FIXED, "LineText" NCLOB MEMORY THRESHOLD 1000, "StageId" INTEGER CS_INT, "ItemName" NVARCHAR(200), "U_ISS_REM" NVARCHAR(50), PRIMARY KEY ("Father", "ChildNum")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "ITT1_VISORDER" ON "UAT_JBF2"."ITT1" ( "Father" ASC, "VisOrder" ASC );
CREATE INDEX "ITT1_FATHER" ON "UAT_JBF2"."ITT1" ( "Father" ASC );
